local core=require 'pa26_core';local catalog=require 'pa26_gender_catalog'
local cases={
 {'/me включил стационарный терминал записи в допросной комнате и положил на стол чистый бланк протокола допроса','/me включила стационарный терминал записи в допросной комнате и положила на стол чистый бланк протокола допроса'},
 {'/me достал из защитного кофра компактный разведывательный дрон с тепловизором, разложил лопасти и запустил его в воздух','/me достала из защитного кофра компактный разведывательный дрон с тепловизором, разложила лопасти и запустила его в воздух'},
 {'/me достав универсальный ключ из подсумка, вставил его в замок наручников, разомкнул браслеты и убрал их на пояс.','/me достав универсальный ключ из подсумка, вставила его в замок наручников, разомкнула браслеты и убрала их на пояс.'},
 {'/me достал служебный КПК, навёл объектив камеры на лицо задержанного и запустил биометрический поиск.','/me достала служебный КПК, навела объектив камеры на лицо задержанного и запустила биометрический поиск.'},
 {'/me снял с разгрузки светошумовую гранату M84, выдернул предохранительную чеку и забросил гранату внутрь помещения','/me сняла с разгрузки светошумовую гранату M84, выдернула предохранительную чеку и забросила гранату внутрь помещения'},
 {'/me резким ударом локтя разбил стекло водительской двери, разблокировал замок изнутри и распахнул дверь.','/me резким ударом локтя разбила стекло водительской двери, разблокировала замок изнутри и распахнула дверь.'},
 {'/me зажал кнопку тангенты рации и передал диспетчеру известные приметы подозреваемого: {appearance}.','/me зажала кнопку тангенты рации и передала диспетчеру известные приметы подозреваемого: {appearance}.'},
 {'/me внёс показания задержанного в итоговый протокол допроса, поставил свою подпись и пододвинул лист задержанному','/me внесла показания задержанного в итоговый протокол допроса, поставила свою подпись и пододвинула лист задержанному'},
}
for _,r in ipairs(cases)do eq(core.expandGender(r[1],'female'),r[2]);eq(core.expandGender(r[1],'male'),r[1])end
local personal='/me достал мой особенный планшет и положил его на капот.'
eq(catalog.template(personal),personal);eq(core.expandGender(personal,'female'),personal,'Do not guess/edit personal prose')
eq(core.expandGender('/me {gender:выдернул|выдернула} чеку и {gender:забросил|забросила} гранату.','female'),'/me выдернула чеку и забросила гранату.')
local path=assert(io.open('moonloader/lib/pa26_gender_catalog.lua','rb'));local text=path:read('*a');path:close()
local oldCount=0
for original,converted in text:gmatch('%["([^"\n]+)"%]="([^"\n]+)"')do
 oldCount=oldCount+1;eq(core.expandGender(original,'male'),original)
 local female=core.expandGender(original,'female');check(not female:find('{gender:',1,true))
 -- Check the entire female sentence, outside variable names. Nouns are deliberately excluded.
 for _,word in ipairs({'встряхнул','выдернул','забросил','защёлкнул','зажал','навёл','положил','пододвинул','разомкнул','распахнул','разложил','сфотографировал'})do
  local plain=female:gsub('{[^{}]*}','')
  check(not plain:find(word..' ',1,true)and not plain:find(word..',',1,true)and not plain:find(word..'%.'))
 end
 eq(core.expandGender(converted,'female'),female)
end
eq(oldCount,76,'Keep every previously supported exact stock sentence')
